// Both the sensor readings and the forecast come from a network of
// stations/areas, not a single point - pick whichever is physically
// closest to home for each.
const cfg = $('Config (edit per location)').item.json;
const tempResp = $('Fetch Air Temperature (data.gov.sg)').item.json.data;
const humResp = $('Fetch Relative Humidity (data.gov.sg)').item.json.data;
const forecastResp = $input.first().json.data;

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function nearestReading(resp) {
  const stationsById = Object.fromEntries(resp.stations.map(s => [s.id, s.location]));
  const readings = resp.readings[0].data;
  const withDist = readings
    .filter(r => stationsById[r.stationId])
    .map(r => ({
      value: r.value,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, stationsById[r.stationId].latitude, stationsById[r.stationId].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].value;
}

function nearestForecast(resp) {
  const areasByName = Object.fromEntries(resp.area_metadata.map(a => [a.name, a.label_location]));
  const forecasts = resp.items[0].forecasts;
  const withDist = forecasts
    .filter(f => areasByName[f.area])
    .map(f => ({
      forecast: f.forecast,
      distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, areasByName[f.area].latitude, areasByName[f.area].longitude)
    }))
    .sort((a, b) => a.distanceKm - b.distanceKm);
  return withDist[0].forecast;
}

// Maps every possible data.gov.sg 2-hour forecast string to one of the
// icons/wx_*.gif files generated by generate_weather_icons.py.
const FORECAST_ICON = {
  'Fair': 'fair_day',
  'Fair (Day)': 'fair_day',
  'Fair (Night)': 'fair_night',
  'Fair and Warm': 'fair_day',
  'Partly Cloudy': 'partly_cloudy_day',
  'Partly Cloudy (Day)': 'partly_cloudy_day',
  'Partly Cloudy (Night)': 'partly_cloudy_night',
  'Cloudy': 'cloudy',
  'Hazy': 'hazy',
  'Slightly Hazy': 'hazy',
  'Windy': 'windy',
  'Mist': 'mist',
  'Fog': 'fog',
  'Light Rain': 'light_rain',
  'Moderate Rain': 'moderate_rain',
  'Heavy Rain': 'heavy_rain',
  'Passing Showers': 'light_rain',
  'Light Showers': 'light_rain',
  'Showers': 'moderate_rain',
  'Heavy Showers': 'heavy_rain',
  'Thundery Showers': 'thunder',
  'Heavy Thundery Showers': 'thunder_heavy',
  'Heavy Thundery Showers with Gusty Winds': 'thunder_wind'
};

const temp = Math.round(nearestReading(tempResp));
const hum = Math.round(nearestReading(humResp));
const forecastText = nearestForecast(forecastResp);
const iconKey = FORECAST_ICON[forecastText] || 'cloudy';

return [{ json: { text: `${temp}°C ${hum}%`, icon: `wx_${iconKey}`, duration: 8, textCase: 2 } }];
